const agentLogs = $('Fetch Agent Activity').all() || [];
const leads = $('Fetch New Leads').all() || [];
const conversations = $('Fetch Conversations').all() || [];
const bookings = $('Fetch Bookings').all() || [];

// Aggregate metrics
const agentBreakdown = {};
for (const log of agentLogs) {
  const aid = log.json.agent_id;
  if (!agentBreakdown[aid]) agentBreakdown[aid] = { total: 0, completed: 0, failed: 0 };
  agentBreakdown[aid].total++;
  if (log.json.status === 'completed') agentBreakdown[aid].completed++;
  if (log.json.status === 'failed') agentBreakdown[aid].failed++;
}

const leadsBySource = {};
for (const l of leads) {
  const src = l.json.source || 'unknown';
  leadsBySource[src] = (leadsBySource[src] || 0) + 1;
}

const bookingsByStatus = {};
for (const b of bookings) {
  const st = b.json.booking_status || 'unknown';
  bookingsByStatus[st] = (bookingsByStatus[st] || 0) + 1;
}

return {
  json: {
    period: { start: new Date(Date.now() - 7*24*60*60*1000).toISOString().split('T')[0], end: new Date().toISOString().split('T')[0] },
    metrics: {
      total_agent_actions: agentLogs.length,
      new_leads: leads.length,
      new_conversations: conversations.length,
      total_bookings: bookings.length,
      confirmed_bookings: bookingsByStatus['confirmed'] || 0
    },
    agent_breakdown: agentBreakdown,
    leads_by_source: leadsBySource,
    bookings_by_status: bookingsByStatus,
    conversion_rate: leads.length > 0 ? ((bookingsByStatus['confirmed'] || 0) / leads.length * 100).toFixed(1) : 0
  }
};

