try { report = JSON.parse(aiResponse); } catch (e) { report = { executive_summary: 'Report generation failed' }; }

return { json: { report_type: 'weekly_analytics', generated_at: new Date().toISOString(), agent_id: 'analytics-analyst', workflow_id: 'WF-ANALYTICS-REPORT', metrics: metrics.metrics, report } };

